import CrudPage from '../../components/ui/CrudPage';
import { assetApi } from '../../api/services';
import { Input, Select, Badge } from '../../components/ui';

const statusColor = { AVAILABLE: 'green', ASSIGNED: 'blue', IN_REPAIR: 'yellow', RETIRED: 'gray' };

const columns = [
  { key: 'assetCode', label: 'Code' },
  { key: 'name', label: 'Name' },
  { key: 'assetType', label: 'Type' },
  { key: 'serialNumber', label: 'Serial No.' },
  { key: 'status', label: 'Status', render: (r) => <Badge label={r.status} color={statusColor[r.status] || 'gray'} /> },
];

function FormFields({ register, errors }) {
  return (
    <>
      <Input label="Asset Name" error={errors.name?.message} {...register('name', { required: 'Required' })} />
      <Input label="Asset Code" error={errors.assetCode?.message} {...register('assetCode', { required: 'Required' })} />
      <Input label="Serial Number" {...register('serialNumber')} />
      <Select label="Asset Type" {...register('assetType')}>
        <option value="">Select Type</option>
        <option value="LAPTOP">Laptop</option>
        <option value="MOBILE">Mobile</option>
        <option value="VEHICLE">Vehicle</option>
        <option value="FURNITURE">Furniture</option>
        <option value="OTHER">Other</option>
      </Select>
      <Select label="Status" {...register('status')}>
        <option value="AVAILABLE">Available</option>
        <option value="ASSIGNED">Assigned</option>
        <option value="IN_REPAIR">In Repair</option>
        <option value="RETIRED">Retired</option>
      </Select>
      <Input label="Purchase Date" type="date" {...register('purchaseDate')} />
    </>
  );
}

export default function AssetsPage() {
  return (
    <CrudPage
      queryKey="assets"
      api={assetApi}
      columns={columns}
      FormFields={FormFields}
      entityName="Asset"
    />
  );
}
